func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
	sort.SliceStable(checkpoints, func(i, j int) bool {
		left := checkpoints[i].CreatedAt
		right := checkpoints[j].CreatedAt
		switch {
		case left.IsZero() && right.IsZero():
			return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
		case left.IsZero():
			return false
		case right.IsZero():
			return true
		case left.Equal(right):
			return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
		default:
			return left.Before(right)
		}
	})
}

type migrateCheckpointOutcome struct {
	missingSessions          int
	compactTranscriptSkipped bool
}

func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
	var outcome migrateCheckpointOutcome

	existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
	if err != nil {
		return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
	}

	if existing != nil && !force {
		// Already in v2. Decide between three cases:
		//   1. Every session has /full artifacts → skip (errAlreadyMigrated).
		//   2. Some sessions are missing /full artifacts → previous run was
		//      interrupted between the /main write and the packer flush;
		//      queue the missing sessions for packing so the next finalize
		//      finishes the job. Don't touch sessions that already have
		//      artifacts.
		//   3. v1 metadata can't be recovered → propagate as a hard error.
		fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
		if err != nil {
			return nil, outcome, err
		}
		if fullCheckpoint == nil {
			return nil, outcome, errAlreadyMigrated
		}
		return fullCheckpoint, outcome, nil
	}

	if existing != nil && force {
		if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
			return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
		}
	}

	summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
	if err != nil {
		return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
	}
	if summary == nil {
		return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
	}

	compactFailed := false
	shouldCopyTaskMetadata := false
	skippedMissingSessions := 0
	migratedSessions := 0
	v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))

		return nil, ErrNoTranscript
	}

	return []byte(content), nil
}

// ReadSessionMetadata reads only the session's metadata.json from the v2
// /main ref. Cheaper than ReadSessionMetadataAndPrompts when the caller only
// needs metadata fields (e.g. SessionID) — skips the prompt and compact
// transcript reads, which is significant for hot loops walking thousands of
// sessions on partial-state repos.
//
// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist
// on /main.
func (s *V2GitStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (CommittedMetadata, error) {
	if err := ctx.Err(); err != nil {
		return CommittedMetadata{}, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return CommittedMetadata{}, ErrCheckpointNotFound
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return CommittedMetadata{}, ErrCheckpointNotFound
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return CommittedMetadata{}, ErrCheckpointNotFound
	}

	sessionTree, err := cpTree.Tree(strconv.Itoa(sessionIndex))
	if err != nil {
		return CommittedMetadata{}, ErrCheckpointNotFound
	}

	metadataFile, err := sessionTree.File(paths.MetadataFileName)
	if err != nil {
		return CommittedMetadata{}, fmt.Errorf("read session metadata file: %w", err)
	}
	content, err := metadataFile.Contents()
	if err != nil {
		return CommittedMetadata{}, fmt.Errorf("read session metadata contents: %w", err)
	}

	var meta CommittedMetadata
	if err := json.Unmarshal([]byte(content), &meta); err != nil {
		return CommittedMetadata{}, fmt.Errorf("parse session metadata: %w", err)
	}
	return meta, nil
}

