// ReadCommitted reads the checkpoint summary from the v2 /main ref.
// Returns nil, nil if the checkpoint doesn't exist (same contract as GitStore.ReadCommitted).
func (s *V2GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Ref doesn't exist means no checkpoint
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Tree not readable
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint subtree not found
	}

	cpFT := s.wrapWithFetcher(ctx, cpTree)
	metadataFile, err := cpFT.File(paths.MetadataFileName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
	}

	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
	}

	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)

func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
		return NewSilentError(err)
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
	out := cmd.OutOrStdout()
	progressOut := cmd.ErrOrStderr()

	result, freshlyPackedRefs, err := migrateCheckpointsV2Internal(ctx, repo, v1Store, v2Store, progressOut, force)
	if err != nil {
		return err
	}

	// Only run the generation-metadata repair pass when the migration
	// actually wrote something. RepairV2GenerationMetadata does a
	// `git ls-remote` plus a transcript-blob walk for every archived
	// /full/<n>, both of which are expensive — multi-second on a healthy
	// network and minutes on a repo with many large archives. On a no-op
	// rerun (everything skipped) there's no new state for repair to
	// reconcile, so paying that cost on every invocation is wrong. When
	// the migration does write archives, freshly-packed refs are excluded
	// since their generation.json is already correct from the packer's
	// in-memory AggregateTranscriptTimestamps.
	var repairResult *strategy.RepairV2GenerationMetadataResult
	if len(freshlyPackedRefs) > 0 {
		var repairErr error
		repairResult, repairErr = strategy.RepairV2GenerationMetadata(ctx, strategy.RepairV2GenerationMetadataOptions{
			ExcludeRefs: freshlyPackedRefs,
		})
		if repairErr != nil {
			return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
		}
		printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
	}

	printMigrateCompletion(out, result)
	fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
	fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
	fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)

	if result.failed > 0 {
		return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
	}
	if repairResult != nil && len(repairResult.Failed) > 0 {
		fmt.Fprintf(out, "%d archived generation(s) failed metadata repair. Check warnings above for details.\n", len(repairResult.Failed))
		return NewSilentError(fmt.Errorf("%d archived generation(s) failed metadata repair", len(repairResult.Failed)))
	}

	return nil
}

